-- VFDA VA Quiz App - Phase 2b database changes (SPEC v2 certification engine).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after phase2.sql (with or without phase3.sql).
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261029160000_v2_certification_engine.sql =====

-- Phase 2b: move the database to SPEC v2 (certification engine), Section 4.
--
-- Keeps: profiles, login and roles (Phase 1), settings, the helper schema.
-- Adds:  workflows, rule_slots, schedule_days, scenarios (master library);
--        offices, office_documents, office_rules, gap_questions,
--        office_workflows, office_scenarios (office overlay);
--        day_unlocks, attempts, attempt_items, certifications,
--        proof_uploads, notifications (VA progress).
-- Moves: clinics -> offices (same ids, so profiles keep their office),
--        interview answers -> office_rules (source 'doctor' or 'vfda'),
--        gray cards -> office_workflows (WF-G1, WF-G2, ...).
-- Old tables: dropped when empty; otherwise kept, renamed legacy_<name>,
--        readable by VFDA admins only (supabase/drop-legacy-tables.sql removes them).
--
-- Works whether or not phase3.sql was run. Runs once: a second run stops
-- with a message and changes nothing.

do $$
begin
  if to_regclass('public.workflows') is not null then
    raise exception 'Phase 2b is already applied (public.workflows exists). Nothing was changed.';
  end if;
end $$;

-- ===========================================================================
-- 1. Offices (replaces clinics). Same ids, so profiles and uploaded files
--    (stored under <office id>/...) stay linked.
-- ===========================================================================

create table public.offices (
  id                  uuid primary key default gen_random_uuid(),
  name                text not null,
  status              text not null default 'setup' check (status in
                        ('setup', 'rules_in_review', 'gap_list', 'scenarios_in_review', 'va_training', 'done')),
  -- Office fields (copied from the matching rule slot answers)
  doctor_name         text,
  team_members        text[] not null default '{}',
  ehr                 text,
  approved_tools      text[] not null default '{}',
  general_preferences text,
  -- Profile flags: decide which days, parts and scenarios the office gets
  bills_insurance     boolean,
  billing_type        text check (billing_type in ('insurance', 'cash', 'both', 'none')),
  has_reexam_card     boolean,
  has_gray_cards      boolean,
  remote_access_tool  text,                       -- null = not answered, 'none' = no remote access
  addons              text[] not null default '{}',
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

alter table public.clinics add column if not exists addons text[] not null default '{}';

insert into public.offices (id, name, status, bills_insurance, billing_type, has_reexam_card,
                            has_gray_cards, remote_access_tool, addons, created_at, updated_at)
select id, name,
       case status
         when 'quizzes_in_review' then 'scenarios_in_review'
         when 'va_training' then 'va_training'
         when 'done' then 'done'
         else 'setup'
       end,
       bills_insurance, billing_type, has_reexam_card, has_gray_cards, remote_access_tool,
       coalesce(addons, '{}'), created_at, updated_at
from public.clinics;

-- Profiles: clinic_id -> office_id, training_start_date -> va_start_date.
do $$
declare
  fk text;
begin
  select conname into fk
  from pg_constraint
  where conrelid = 'public.profiles'::regclass and contype = 'f'
    and confrelid = 'public.clinics'::regclass;
  if fk is not null then
    execute format('alter table public.profiles drop constraint %I', fk);
  end if;
end $$;

drop policy if exists "doctor reads own clinic profiles" on public.profiles;
alter table public.profiles rename column clinic_id to office_id;
alter table public.profiles rename column training_start_date to va_start_date;
alter table public.profiles
  add constraint profiles_office_id_fkey foreign key (office_id)
  references public.offices (id) on delete set null;

-- ===========================================================================
-- 2. Master library (Layer 1), loaded from seed/quiz-bank-v2.json.
-- ===========================================================================

-- One standard workflow, e.g. WF01 New patient scheduling.
create table public.workflows (
  id                   uuid primary key default gen_random_uuid(),
  code                 text not null unique,
  name                 text not null,
  trigger              text not null default '',
  required_information text[] not null default '{}',
  steps                text[] not null default '{}',
  definition_of_done   text not null default '',
  va_can_decide        text[] not null default '{}',
  requires_approval    text[] not null default '{}',
  immediate_escalation text[] not null default '{}',
  common_mistakes      text[] not null default '{}',
  prohibited_actions   text[] not null default '{}',
  pass_standard        text not null default '',
  sop_outline          text[] not null default '{}',
  bank_refs            text[] not null default '{}',
  rule_keys            text[] not null default '{}',   -- office rule keys this workflow uses
  test_scenarios       text[] not null default '{}',   -- '<day>-<code>', e.g. 'W1D1-D1'
  position             integer not null default 0,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

-- One office rule the app needs, e.g. LATE_CANCEL_RULE.
create table public.rule_slots (
  id             uuid primary key default gen_random_uuid(),
  key            text not null unique,
  question       text not null,
  answer_type    text not null check (answer_type in ('text', 'list', 'yesno', 'choice', 'upload', 'matrix')),
  condition      text not null default 'always',   -- a key of settings.conditions
  card_source    text not null default '',
  workflows      text[] not null default '{}',
  schedule_day   text not null,                    -- 'PROFILE' or a day code like 'W1D1'
  default_answer jsonb,                            -- VFDA default ("Keep VFDA default?")
  position       integer not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

-- One training day, W1D1 ... W2D5.
create table public.schedule_days (
  id                uuid primary key default gen_random_uuid(),
  code              text not null unique,
  week              smallint not null check (week between 1 and 2),
  day               smallint not null check (day between 1 and 5),
  title             text not null,
  cards             text[] not null default '{}',
  condition         text not null default 'always',
  max_points        integer check (max_points > 0),  -- null for W2D5: set per office
  pass_points       integer,
  review_min_points integer,
  answer_format     text not null check (answer_format in ('steps_say_doc', 'say_do_book')),
  proof_of_work     text[] not null default '{}',
  workflows         text[] not null default '{}',
  notes             text not null default '',
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (week, day),
  check (
    (max_points is null and pass_points is null and review_min_points is null)
    or (max_points is not null and pass_points is not null and review_min_points is not null
        and review_min_points <= pass_points and pass_points <= max_points)
  )
);

-- One master scenario. Holds answer keys: VFDA admins only.
create table public.scenarios (
  id               uuid primary key default gen_random_uuid(),
  schedule_day     text not null references public.schedule_days (code) on update cascade,
  code             text not null,                  -- 'A1', 'B3', ...
  version          text not null default 'A' check (version in ('A', 'B')),
  workflow         text not null references public.workflows (code) on update cascade,
  part             text not null,                  -- 'A', 'B', 'B-alt', ...
  part_title       text not null default '',
  condition        text not null default 'always',
  type             text not null check (type in ('mc', 'situational')),
  stem             text not null,
  options          jsonb,                          -- fixed options (mc)
  options_rule     text,                           -- or a rule for building them per office
  answer           text,                           -- mc answer letter
  correct_response jsonb,                          -- list, or {Say, Do, Book}
  critical_fail    text,
  escalation_level text not null default 'none' check (escalation_level in ('none', 'approval', 'immediate')),
  bank_ref         text not null default '',
  points           smallint not null check (points in (1, 2)),
  answer_format    text check (answer_format in ('steps_say_doc', 'say_do_book')),
  repeat_variant   text,                           -- 'generate', or null for mc
  test_status      text not null default 'draft' check (test_status in ('draft', 'vfda_reviewed', 'live')),
  position         integer not null default 0,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (schedule_day, code, version)
);
create index on public.scenarios (workflow);

-- ===========================================================================
-- 3. Office overlay (Layer 2).
-- ===========================================================================

-- One uploaded Trello card PDF or SOP. Files live in the private
-- 'office-documents' bucket under <office id>/...
create table public.office_documents (
  id             uuid primary key default gen_random_uuid(),
  office_id      uuid not null references public.offices (id) on delete cascade,
  kind           text not null default 'card' check (kind in ('card', 'sop')),
  file_path      text not null,
  file_name      text not null default '',
  uploaded_by    uuid references public.profiles (id) on delete set null,
  extracted_text text,
  imported_at    timestamptz,                       -- when rules were extracted from it
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index on public.office_documents (office_id);

-- One office rule. A rule typed in directly (by the doctor or VFDA) has no
-- source_document; rules extracted from a card PDF point to it, so the same
-- key can have several proposals side by side (e.g. conflicting cards).
create table public.office_rules (
  id                 uuid primary key default gen_random_uuid(),
  office_id          uuid not null references public.offices (id) on delete cascade,
  rule_slot_key      text not null,                 -- foreign key added below
  rule               jsonb,                         -- the value, shaped by the slot's answer_type
  attachments        jsonb not null default '[]',   -- uploaded files (interview-uploads bucket)
  source             text not null check (source in ('card_import', 'doctor', 'vfda_default', 'vfda')),
  source_document_id uuid references public.office_documents (id) on delete restrict,
  source_quote       text,
  status             text not null default 'proposed' check (status in
                       ('proposed', 'accepted', 'needs_doctor', 'rejected')),
  effective_date     date not null default current_date,
  workflows          text[] not null default '{}',  -- related workflow codes
  doctor_approved_by uuid references public.profiles (id) on delete set null,
  doctor_approved_at timestamptz,
  vfda_reviewed_by   uuid references public.profiles (id) on delete set null,
  vfda_reviewed_at   timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique nulls not distinct (office_id, rule_slot_key, source_document_id),
  constraint office_rules_size
    check (octet_length(coalesce(rule::text, '')) + octet_length(attachments::text) <= 200000)
);
create index on public.office_rules (rule_slot_key);
create index on public.office_rules (source_document_id);

-- One clarifying or edge-case question for the doctor.
create table public.gap_questions (
  id            uuid primary key default gen_random_uuid(),
  office_id     uuid not null references public.offices (id) on delete cascade,
  rule_slot_key text references public.rule_slots (key) on update cascade,
  workflow      text,                               -- for edge cases: a workflow code
  question      text not null,
  reason        text not null check (reason in ('not_found', 'partial', 'conflicting', 'edge_case')),
  answer        jsonb,
  answered_by   uuid references public.profiles (id) on delete set null,
  answered_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check (rule_slot_key is not null or workflow is not null)
);
create index on public.gap_questions (office_id);

-- Gray card workflows for one office: WF-G1, WF-G2, ... Same fields as
-- workflows. card_answers holds the gray card questions (CARD_NAME, ...);
-- name, trigger, steps, inputs, done, escalation and frequency follow them.
create table public.office_workflows (
  id                   uuid primary key default gen_random_uuid(),
  office_id            uuid not null references public.offices (id) on delete cascade,
  code                 text not null,
  name                 text not null default '',
  trigger              text not null default '',
  required_information text[] not null default '{}',
  steps                text[] not null default '{}',
  definition_of_done   text not null default '',
  va_can_decide        text[] not null default '{}',
  requires_approval    text[] not null default '{}',
  immediate_escalation text[] not null default '{}',
  common_mistakes      text[] not null default '{}',
  prohibited_actions   text[] not null default '{}',
  pass_standard        text not null default '',
  sop_outline          text[] not null default '{}',
  rule_keys            text[] not null default '{}',
  card_answers         jsonb not null default '{}',
  risk_tag             text check (risk_tag in ('high_risk', 'frequent', 'occasional')),
  frequency            text,
  position             integer not null default 0,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (office_id, code),
  check (code ~ '^WF-G[0-9]+$')
);

-- One filled scenario for one office. Holds answer keys: never readable by VAs
-- (see get_open_day_scenarios). Display fields are copied in so gray card
-- scenarios, which have no master scenario, work the same way.
create table public.office_scenarios (
  id                 uuid primary key default gen_random_uuid(),
  office_id          uuid not null references public.offices (id) on delete cascade,
  scenario_id        uuid references public.scenarios (id) on delete set null,
  office_workflow_id uuid references public.office_workflows (id) on delete set null,
  schedule_day       text not null references public.schedule_days (code) on update cascade,
  version            text not null default 'A' check (version in ('A', 'B')),
  workflow           text not null,                 -- 'WF01' ... or 'WF-G1' ...
  part               text not null,
  part_title         text not null default '',
  code               text not null,
  type               text not null check (type in ('mc', 'situational')),
  points             smallint not null check (points in (1, 2)),
  answer_format      text check (answer_format in ('steps_say_doc', 'say_do_book')),
  stem               text not null,
  options            jsonb,
  answer             text,
  correct_response   jsonb,
  critical_fail      text,
  escalation_level   text not null default 'none' check (escalation_level in ('none', 'approval', 'immediate')),
  is_repeat_variant  boolean not null default false,
  parent_scenario_id uuid references public.office_scenarios (id) on delete cascade,
  test_status        text not null default 'draft' check (test_status in ('draft', 'vfda_reviewed', 'live')),
  edited_by_vfda     boolean not null default false,
  position           integer not null default 0,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check (is_repeat_variant = (parent_scenario_id is not null))
);
create unique index office_scenarios_one_per_code
  on public.office_scenarios (office_id, schedule_day, version, code) where not is_repeat_variant;
create unique index office_scenarios_one_repeat
  on public.office_scenarios (parent_scenario_id) where is_repeat_variant;
create index on public.office_scenarios (scenario_id);

-- ===========================================================================
-- 4. Carry over Phase 3 interview answers and gray cards, if there are any.
-- ===========================================================================

-- Every non-click-path interview key is a rule slot in v2 with the same answer
-- type. Click paths are gone in v2 and stay behind in legacy_interview_answers.
insert into public.office_rules (office_id, rule_slot_key, rule, attachments, source, status,
                                 doctor_approved_by, doctor_approved_at,
                                 vfda_reviewed_by, vfda_reviewed_at, created_at, updated_at)
select a.clinic_id, a.question_key, a.value, a.attachments,
       case when p.role = 'doctor' then 'doctor' else 'vfda' end,
       'accepted',
       case when p.role = 'doctor' then a.answered_by end,
       case when p.role = 'doctor' then a.updated_at end,
       case when p.role is distinct from 'doctor' then a.answered_by end,
       case when p.role is distinct from 'doctor' then a.updated_at end,
       a.created_at, a.updated_at
from public.interview_answers a
join public.interview_questions q on q.key = a.question_key
left join public.profiles p on p.id = a.answered_by
where q.answer_type <> 'click_path';

-- rule_slots is filled by `npm run import:bank` after this runs. NOT VALID
-- skips checking the rows copied above (their keys arrive with the import);
-- every new row is checked.
alter table public.office_rules
  add constraint office_rules_rule_slot_key_fkey foreign key (rule_slot_key)
  references public.rule_slots (key) on update cascade not valid;

insert into public.office_workflows (office_id, code, card_answers, risk_tag, frequency, position,
                                     created_at, updated_at)
select clinic_id,
       'WF-G' || row_number() over (partition by clinic_id order by position, created_at),
       answers, risk_tag, frequency, position, created_at, updated_at
from public.gray_cards;

-- ===========================================================================
-- 5. Retire the v1 tables. Policies, triggers and helpers that point at them
--    go first; then each table is dropped if empty, or kept as legacy_<name>.
-- ===========================================================================

drop function if exists public.get_open_quiz_items(uuid);
drop trigger if exists sync_profile_answer on public.interview_answers;
drop trigger if exists guard_gray_card on public.gray_cards;
drop function if exists private.sync_profile_answer();
drop function if exists private.guard_gray_card();
drop policy if exists "doctor reads interview settings" on public.settings;
drop policy if exists "interview uploads: admin full access" on storage.objects;
drop policy if exists "interview uploads: doctor reads own clinic" on storage.objects;
drop policy if exists "interview uploads: doctor adds to own clinic" on storage.objects;
drop policy if exists "interview uploads: doctor deletes own clinic" on storage.objects;

do $$
declare
  t   text;
  pol record;
  n   bigint;
begin
  -- Children before parents, so foreign keys don't block a drop.
  foreach t in array array[
    'notifications', 'attempts', 'proof_uploads', 'unlocks', 'clinic_questions',
    'clinic_quizzes', 'interview_answers', 'gray_cards', 'question_templates',
    'quiz_templates', 'interview_questions', 'clinics'
  ] loop
    continue when to_regclass('public.' || t) is null;

    for pol in select policyname from pg_policies where schemaname = 'public' and tablename = t loop
      execute format('drop policy %I on public.%I', pol.policyname, t);
    end loop;

    execute format('select count(*) from public.%I', t) into n;
    if n = 0 then
      begin
        execute format('drop table public.%I', t);
        raise notice 'Dropped empty table %', t;
        continue;
      exception when dependent_objects_still_exist then
        null;  -- a kept legacy table still points at it: keep this one too
      end;
    end if;

    execute format('alter table public.%I rename to %I', t, 'legacy_' || t);
    execute format(
      'create policy "admin reads legacy data" on public.%I for select to authenticated using ((select private.is_admin()))',
      'legacy_' || t);
    raise notice 'Kept % (% rows) as legacy_%', t, n, t;
  end loop;
end $$;

drop function if exists private.va_has_unlock(uuid);
drop function if exists private.is_doctor_of_clinic_quiz(uuid);
drop function if exists private.is_doctor_of_clinic(uuid);
drop function if exists private.my_clinic_id();

-- ===========================================================================
-- 6. VA progress.
-- ===========================================================================

-- One VA's status on one training day.
create table public.day_unlocks (
  id            uuid primary key default gen_random_uuid(),
  va_id         uuid not null references public.profiles (id) on delete cascade,
  schedule_day  text not null references public.schedule_days (code) on update cascade,
  version       text not null default 'A' check (version in ('A', 'B')),  -- B after a retake
  status        text not null default 'locked' check (status in
                  ('locked', 'open', 'submitted', 'passed', 'in_review', 'retake')),
  cards_done_at timestamptz,
  unlocked_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (va_id, schedule_day)
);
create index on public.day_unlocks (schedule_day);

-- One day attempt (version A, or B after a retake).
create table public.attempts (
  id                   uuid primary key default gen_random_uuid(),
  va_id                uuid not null references public.profiles (id) on delete cascade,
  office_id            uuid not null references public.offices (id) on delete cascade,
  schedule_day         text not null references public.schedule_days (code) on update cascade,
  version              text not null default 'A' check (version in ('A', 'B')),
  started_at           timestamptz not null default now(),
  submitted_at         timestamptz,
  first_try_points     numeric(6, 2),
  max_points           integer,
  result               text check (result in ('pass', 'review', 'retake')),
  critical_errors      integer not null default 0,
  time_spent           integer,                      -- seconds
  paste_log            jsonb not null default '[]',  -- logged, never blocked
  feedback_released_at timestamptz,                  -- the VA sees results only after this
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (va_id, schedule_day, version)
);
create index on public.attempts (office_id);
create index on public.attempts (schedule_day);

-- One scenario inside an attempt: first answer and, below 2/2, the immediate repeat.
create table public.attempt_items (
  id                 uuid primary key default gen_random_uuid(),
  attempt_id         uuid not null references public.attempts (id) on delete cascade,
  office_scenario_id uuid not null references public.office_scenarios (id) on delete restrict,
  position           integer not null default 0,
  first_answer       jsonb,
  first_score        smallint check (first_score between 0 and 2),
  first_feedback     jsonb,                          -- {reason, missed_steps: []}
  repeat_scenario_id uuid references public.office_scenarios (id) on delete restrict,
  repeat_answer      jsonb,
  repeat_score       smallint check (repeat_score between 0 and 2),
  repeat_feedback    jsonb,
  critical_error     boolean not null default false,
  critical_quote     text,                           -- the VA's exact words
  ai_confidence      numeric(3, 2) check (ai_confidence between 0 and 1),
  time_per_item      integer,                        -- seconds
  vfda_override      jsonb,                          -- {score, note, by, at}
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (attempt_id, office_scenario_id)
);
create index on public.attempt_items (office_scenario_id);
create index on public.attempt_items (repeat_scenario_id);

-- One VA on one workflow (standard, or the office's gray card workflow).
create table public.certifications (
  id                 uuid primary key default gen_random_uuid(),
  va_id              uuid not null references public.profiles (id) on delete cascade,
  workflow           text references public.workflows (code) on update cascade,
  office_workflow_id uuid references public.office_workflows (id) on delete cascade,
  status             text not null default 'pending' check (status in ('pending', 'retrain', 'certified')),
  attempts           integer not null default 0,
  errors             integer not null default 0,
  sop_text           text,
  sop_link           text,
  sop_submitted_at   timestamptz,
  doctor_decision    text check (doctor_decision in ('approved', 'corrected', 'rejected')),
  doctor_notes       text,
  doctor_decided_by  uuid references public.profiles (id) on delete set null,
  doctor_decided_at  timestamptz,
  certified_at       timestamptz,
  recheck_date       date,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check (num_nonnulls(workflow, office_workflow_id) = 1),
  unique (va_id, workflow),
  unique (va_id, office_workflow_id)
);
create index on public.certifications (office_workflow_id);

-- One proof-of-work file or Loom link for a day.
create table public.proof_uploads (
  id           uuid primary key default gen_random_uuid(),
  va_id        uuid not null references public.profiles (id) on delete cascade,
  schedule_day text not null references public.schedule_days (code) on update cascade,
  file_path    text,                                 -- path in Supabase Storage
  link_url     text,
  status       text not null default 'pending' check (status in ('pending', 'accepted', 'redo')),
  review_note  text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  check (file_path is not null or link_url is not null)
);
create index on public.proof_uploads (va_id);

-- One report sent (about an attempt or a certification / SOP decision).
create table public.notifications (
  id               uuid primary key default gen_random_uuid(),
  attempt_id       uuid references public.attempts (id) on delete cascade,
  certification_id uuid references public.certifications (id) on delete cascade,
  channel          text not null check (channel in ('email', 'slack')),
  recipient        text not null,
  sent_at          timestamptz,
  error            text,
  created_at       timestamptz not null default now(),
  check (num_nonnulls(attempt_id, certification_id) = 1)
);
create index on public.notifications (attempt_id);
create index on public.notifications (certification_id);

-- updated_at on every new table that has one.
do $$
declare
  t text;
begin
  foreach t in array array[
    'offices', 'workflows', 'rule_slots', 'schedule_days', 'scenarios', 'office_documents',
    'office_rules', 'gap_questions', 'office_workflows', 'office_scenarios', 'day_unlocks',
    'attempts', 'attempt_items', 'certifications', 'proof_uploads'
  ] loop
    execute format(
      'create trigger set_updated_at before update on public.%I for each row execute function private.set_updated_at()', t);
  end loop;
end $$;

-- ===========================================================================
-- 7. Triggers that keep office data consistent, whoever writes it.
-- ===========================================================================

-- Direct answers (no source document) to profile and office-field slots are
-- copied onto the office. Doctors can't update offices; this does it for them.
-- yes/no slots store "yes"/"no"; REMOTE_ACCESS_TOOL "none"/"no"/"n/a" = none.
create or replace function private.sync_office_fields()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  r    public.office_rules;
  v    jsonb;
  txt  text;
  list text[];
begin
  if tg_op = 'DELETE' then
    r := old;
    v := null;
  else
    r := new;
    v := new.rule;
  end if;
  if r.source_document_id is not null then
    return null;
  end if;
  txt := case when jsonb_typeof(v) = 'string' then nullif(btrim(v #>> '{}'), '') end;
  list := coalesce((
    select array_agg(btrim(e))
    from jsonb_array_elements_text(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end) e
    where btrim(e) <> ''
  ), '{}');

  case r.rule_slot_key
    when 'BILLS_INSURANCE' then
      update public.offices set bills_insurance =
        case lower(txt) when 'yes' then true when 'no' then false end
      where id = r.office_id;
    when 'HAS_REEXAM_CARD' then
      update public.offices set has_reexam_card =
        case lower(txt) when 'yes' then true when 'no' then false end
      where id = r.office_id;
    when 'HAS_GRAY_CARDS' then
      update public.offices set has_gray_cards =
        case lower(txt) when 'yes' then true when 'no' then false end
      where id = r.office_id;
    when 'BILLING_TYPE' then
      update public.offices set billing_type =
        case when lower(txt) in ('insurance', 'cash', 'both', 'none') then lower(txt) end
      where id = r.office_id;
    when 'REMOTE_ACCESS_TOOL' then
      update public.offices set remote_access_tool =
        case
          when txt is null then null
          when lower(txt) in ('none', 'no', 'n/a', 'na', 'nothing', '-') then 'none'
          else txt
        end
      where id = r.office_id;
    when 'ADDONS' then
      update public.offices set addons = list where id = r.office_id;
    when 'DOCTOR_NAME' then
      update public.offices set doctor_name = txt where id = r.office_id;
    when 'EHR_NAME' then
      update public.offices set ehr = txt where id = r.office_id;
    when 'TEAM_MEMBERS' then
      update public.offices set team_members = list where id = r.office_id;
    when 'APPROVED_TOOLS' then
      update public.offices set approved_tools = list where id = r.office_id;
    when 'GENERAL_PREFERENCES' then
      update public.offices set general_preferences = txt where id = r.office_id;
    else
      null;
  end case;
  return null;
end;
$$;

create trigger sync_office_fields
  after insert or update of rule or delete on public.office_rules
  for each row execute function private.sync_office_fields();

-- A doctor's write is always the doctor's own, accepted answer: they can't
-- pose as VFDA or a card import, or mark VFDA review. VFDA (and the service
-- role / SQL Editor, where auth.uid() is null) write anything.
create or replace function private.guard_office_rule()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_admin() then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    new.office_id          := old.office_id;
    new.rule_slot_key      := old.rule_slot_key;
    new.source_document_id := old.source_document_id;
    new.source_quote       := old.source_quote;
    new.vfda_reviewed_by   := old.vfda_reviewed_by;
    new.vfda_reviewed_at   := old.vfda_reviewed_at;
    if new.rule is distinct from old.rule or new.attachments is distinct from old.attachments then
      new.source := 'doctor';
    else
      new.source := old.source;
    end if;
  else
    new.source             := 'doctor';
    new.source_document_id := null;
    new.source_quote       := null;
    new.vfda_reviewed_by   := null;
    new.vfda_reviewed_at   := null;
  end if;
  new.status             := 'accepted';
  new.doctor_approved_by := (select auth.uid());
  new.doctor_approved_at := now();
  return new;
end;
$$;

create trigger guard_office_rule
  before insert or update on public.office_rules
  for each row execute function private.guard_office_rule();

-- Doctors only answer gap questions; everything else stays as VFDA wrote it.
create or replace function private.guard_gap_question()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null or private.is_admin() then
    return new;
  end if;
  new.office_id     := old.office_id;
  new.rule_slot_key := old.rule_slot_key;
  new.workflow      := old.workflow;
  new.question      := old.question;
  new.reason        := old.reason;
  new.answered_by   := (select auth.uid());
  new.answered_at   := now();
  return new;
end;
$$;

create trigger guard_gap_question
  before update on public.gap_questions
  for each row execute function private.guard_gap_question();

-- Gray card workflows: the next free WF-G code; only VFDA sets the risk tag;
-- name, trigger, inputs, steps, done, escalation and frequency follow the
-- card answers whenever those change.
create or replace function private.guard_office_workflow()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  a jsonb := coalesce(new.card_answers, '{}');
begin
  if tg_op = 'INSERT' and coalesce(new.code, '') = '' then
    perform pg_advisory_xact_lock(hashtext('office_workflows:' || new.office_id::text));
    select 'WF-G' || (coalesce(max(substring(w.code from '^WF-G([0-9]+)$')::int), 0) + 1)
      into new.code
    from public.office_workflows w
    where w.office_id = new.office_id;
  end if;

  if (select auth.uid()) is not null and not private.is_admin() then
    if tg_op = 'INSERT' then
      new.risk_tag := null;
    else
      new.risk_tag := old.risk_tag;
      new.code := old.code;
    end if;
  end if;

  if tg_op = 'INSERT' or new.card_answers is distinct from old.card_answers then
    new.name                 := coalesce(nullif(btrim(a ->> 'CARD_NAME'), ''), '');
    new.trigger              := coalesce(btrim(a ->> 'CARD_TRIGGER'), '');
    new.definition_of_done   := coalesce(btrim(a ->> 'CARD_DONE'), '');
    new.required_information := private.lines(a ->> 'CARD_INPUTS');
    new.steps                := private.lines(a ->> 'CARD_STEPS');
    new.immediate_escalation := private.lines(a ->> 'CARD_ESCALATION');
    new.frequency            := nullif(btrim(coalesce(a ->> 'CARD_FREQUENCY', '')), '');
  end if;
  return new;
end;
$$;

-- Non-blank lines of a text answer, trimmed, without list bullets/numbers.
create or replace function private.lines(p_text text)
returns text[]
language sql immutable
set search_path = ''
as $$
  select coalesce(array_agg(l order by n), '{}')
  from (
    select n, btrim(regexp_replace(line, '^\s*([-*•]|[0-9]+[.)])\s*', '')) as l
    from unnest(string_to_array(coalesce(p_text, ''), E'\n')) with ordinality as x(line, n)
  ) s
  where l <> '';
$$;

create trigger guard_office_workflow
  before insert or update on public.office_workflows
  for each row execute function private.guard_office_workflow();

-- Refill gray card workflows copied in section 4 (the trigger didn't exist yet).
update public.office_workflows w set
  name                 = coalesce(nullif(btrim(card_answers ->> 'CARD_NAME'), ''), ''),
  trigger              = coalesce(btrim(card_answers ->> 'CARD_TRIGGER'), ''),
  definition_of_done   = coalesce(btrim(card_answers ->> 'CARD_DONE'), ''),
  required_information = private.lines(card_answers ->> 'CARD_INPUTS'),
  steps                = private.lines(card_answers ->> 'CARD_STEPS'),
  immediate_escalation = private.lines(card_answers ->> 'CARD_ESCALATION');

-- Doctors decide on SOPs; nothing else about a certification.
create or replace function private.guard_certification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  decision text := new.doctor_decision;
  notes    text := new.doctor_notes;
begin
  if (select auth.uid()) is null or private.is_admin() then
    return new;
  end if;
  new := old;
  new.doctor_decision   := decision;
  new.doctor_notes      := notes;
  new.doctor_decided_by := (select auth.uid());
  new.doctor_decided_at := now();
  return new;
end;
$$;

create trigger guard_certification
  before update on public.certifications
  for each row execute function private.guard_certification();

-- ===========================================================================
-- 8. Row-level security.
--   vfda_admin: everything.
--   doctor:     own office only (rules, gap questions, VA progress, SOPs).
--   va:         own progress only; scenarios only through
--               get_open_day_scenarios(), never answer keys.
-- The service-role key (server only) bypasses this for grading and reports.
-- ===========================================================================

create or replace function private.my_office_id()
returns uuid
language sql stable security definer
set search_path = ''
as $$
  select office_id from public.profiles where id = (select auth.uid());
$$;

-- True when the caller is the doctor of this office.
create or replace function private.is_doctor_of_office(p_office_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce(private.my_role() = 'doctor' and private.my_office_id() = p_office_id, false);
$$;

-- True when the caller is the doctor of this VA's office.
create or replace function private.is_doctor_of_va(p_va_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce(private.my_role() = 'doctor' and exists (
    select 1 from public.profiles p
    where p.id = p_va_id and p.role = 'va' and p.office_id = private.my_office_id()
  ), false);
$$;

-- True when the caller is a VA and this is them.
create or replace function private.is_me_as_va(p_va_id uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select coalesce(p_va_id = (select auth.uid()) and private.my_role() = 'va', false);
$$;

grant usage on schema private to authenticated;
grant execute on all functions in schema private to authenticated;

do $$
declare
  t text;
begin
  foreach t in array array[
    'offices', 'workflows', 'rule_slots', 'schedule_days', 'scenarios', 'office_documents',
    'office_rules', 'gap_questions', 'office_workflows', 'office_scenarios', 'day_unlocks',
    'attempts', 'attempt_items', 'certifications', 'proof_uploads', 'notifications'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format(
      'create policy "admin full access" on public.%I for all to authenticated '
      'using ((select private.is_admin())) with check ((select private.is_admin()))', t);
  end loop;
end $$;

-- Profiles: doctors see the people in their office.
create policy "doctor reads own office profiles" on public.profiles
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

-- Settings doctors need for office setup. Grading and the rest stay admin-only.
create policy "doctor reads setup settings" on public.settings
  for select to authenticated
  using ((select private.my_role()) = 'doctor'
         and key in ('conditions', 'gray_card_questions', 'office_fields', 'gray_card_workflow_fields'));

-- Master library: workflows and days have no answer keys. Rule slots are the
-- doctor's questions. Master scenarios hold answer keys: admin only.
create policy "doctor and va read workflows" on public.workflows
  for select to authenticated
  using ((select private.my_role()) in ('doctor', 'va'));
create policy "doctor and va read schedule days" on public.schedule_days
  for select to authenticated
  using ((select private.my_role()) in ('doctor', 'va'));
create policy "doctor reads rule slots" on public.rule_slots
  for select to authenticated
  using ((select private.my_role()) = 'doctor');

-- Office overlay: doctor sees their own office.
create policy "doctor and va read own office" on public.offices
  for select to authenticated
  using (id = (select private.my_office_id()) and (select private.my_role()) in ('doctor', 'va'));

create policy "doctor reads own documents" on public.office_documents
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

create policy "doctor reads own rules" on public.office_rules
  for select to authenticated
  using (private.is_doctor_of_office(office_id));
create policy "doctor adds own rules" on public.office_rules
  for insert to authenticated
  with check (private.is_doctor_of_office(office_id));
create policy "doctor approves or corrects own rules" on public.office_rules
  for update to authenticated
  using (private.is_doctor_of_office(office_id))
  with check (private.is_doctor_of_office(office_id));
create policy "doctor deletes own answers" on public.office_rules
  for delete to authenticated
  using (private.is_doctor_of_office(office_id) and source = 'doctor' and source_document_id is null);

create policy "doctor reads own gap questions" on public.gap_questions
  for select to authenticated
  using (private.is_doctor_of_office(office_id));
create policy "doctor answers own gap questions" on public.gap_questions
  for update to authenticated
  using (private.is_doctor_of_office(office_id))
  with check (private.is_doctor_of_office(office_id));

create policy "doctor manages own gray card workflows" on public.office_workflows
  for all to authenticated
  using (private.is_doctor_of_office(office_id))
  with check (private.is_doctor_of_office(office_id));

create policy "doctor reads own scenarios" on public.office_scenarios
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

-- Progress: VAs read their own rows (scores only once released); doctors read
-- their VAs'. Unlocks, attempts and grades are written by the server.
create policy "va reads own day unlocks" on public.day_unlocks
  for select to authenticated
  using (private.is_me_as_va(va_id));
create policy "doctor reads own VAs' day unlocks" on public.day_unlocks
  for select to authenticated
  using (private.is_doctor_of_va(va_id));

create policy "va reads own released attempts" on public.attempts
  for select to authenticated
  using (private.is_me_as_va(va_id) and feedback_released_at is not null);
create policy "doctor reads own VAs' attempts" on public.attempts
  for select to authenticated
  using (private.is_doctor_of_va(va_id));

create policy "va reads own released attempt items" on public.attempt_items
  for select to authenticated
  using (exists (
    select 1 from public.attempts a
    where a.id = attempt_id and private.is_me_as_va(a.va_id) and a.feedback_released_at is not null
  ));
create policy "doctor reads own VAs' attempt items" on public.attempt_items
  for select to authenticated
  using (exists (
    select 1 from public.attempts a where a.id = attempt_id and private.is_doctor_of_va(a.va_id)
  ));

create policy "va reads own certifications" on public.certifications
  for select to authenticated
  using (private.is_me_as_va(va_id));
create policy "doctor reads own VAs' certifications" on public.certifications
  for select to authenticated
  using (private.is_doctor_of_va(va_id));
create policy "doctor decides own VAs' SOPs" on public.certifications
  for update to authenticated
  using (private.is_doctor_of_va(va_id) and sop_submitted_at is not null)
  with check (private.is_doctor_of_va(va_id));

create policy "va reads own proof uploads" on public.proof_uploads
  for select to authenticated
  using (private.is_me_as_va(va_id));
create policy "va adds own proof uploads" on public.proof_uploads
  for insert to authenticated
  with check (
    private.is_me_as_va(va_id)
    and status = 'pending'
    and review_note is null
    and exists (
      select 1 from public.day_unlocks u
      where u.va_id = (select auth.uid())
        and u.schedule_day = proof_uploads.schedule_day
        and u.status <> 'locked'
    )
  );
create policy "doctor reads own VAs' proof uploads" on public.proof_uploads
  for select to authenticated
  using (private.is_doctor_of_va(va_id));

create policy "doctor reads own office reports" on public.notifications
  for select to authenticated
  using (
    exists (select 1 from public.attempts a where a.id = attempt_id and private.is_doctor_of_va(a.va_id))
    or exists (select 1 from public.certifications c where c.id = certification_id and private.is_doctor_of_va(c.va_id))
  );

-- ---------------------------------------------------------------------------
-- The only way a VA reads scenarios: display columns only (never answer,
-- correct_response, critical_fail or escalation level), only VFDA-approved
-- ('live') ones, only for the day open to this VA right now, in the version
-- they're on. Repeat variants are served by the server after grading.
-- ---------------------------------------------------------------------------

create or replace function public.get_open_day_scenarios(p_schedule_day text)
returns table (
  id            uuid,
  "position"    integer,
  workflow      text,
  part          text,
  part_title    text,
  code          text,
  type          text,
  points        smallint,
  answer_format text,
  stem          text,
  options       jsonb
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_version text;
begin
  select u.version into v_version
  from public.day_unlocks u
  where u.va_id = (select auth.uid())
    and u.schedule_day = p_schedule_day
    and u.status = 'open'
    and private.my_role() = 'va';
  if v_version is null then
    raise exception 'This day is not open for you.' using errcode = '42501';
  end if;

  return query
    select s.id, s.position, s.workflow, s.part, s.part_title, s.code, s.type,
           s.points, coalesce(s.answer_format, d.answer_format), s.stem, s.options
    from public.office_scenarios s
    join public.schedule_days d on d.code = s.schedule_day
    where s.office_id = private.my_office_id()
      and s.schedule_day = p_schedule_day
      and s.version = v_version
      and not s.is_repeat_variant
      and s.test_status = 'live'
    order by s.position, s.code;
end;
$$;

revoke all on function public.get_open_day_scenarios(text) from public, anon;
grant execute on function public.get_open_day_scenarios(text) to authenticated;

-- ===========================================================================
-- 9. Storage. Files live under <office id>/... in private buckets.
-- ===========================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('interview-uploads', 'interview-uploads', false, 52428800, array[
    'image/*', 'application/pdf', 'text/plain', 'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'video/mp4', 'video/quicktime', 'video/webm']),
  ('office-documents', 'office-documents', false, 52428800, array[
    'application/pdf', 'text/plain', 'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'])
on conflict (id) do update set
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- Rule uploads (scripts, templates): VFDA everything; doctors their own office.
create policy "interview uploads: admin full access" on storage.objects
  for all to authenticated
  using (bucket_id = 'interview-uploads' and (select private.is_admin()))
  with check (bucket_id = 'interview-uploads' and (select private.is_admin()));
create policy "interview uploads: doctor reads own office" on storage.objects
  for select to authenticated
  using (bucket_id = 'interview-uploads' and (select private.my_role()) = 'doctor'
         and (storage.foldername(name))[1] = (select private.my_office_id())::text);
create policy "interview uploads: doctor adds to own office" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'interview-uploads' and (select private.my_role()) = 'doctor'
              and (storage.foldername(name))[1] = (select private.my_office_id())::text);
create policy "interview uploads: doctor deletes own office" on storage.objects
  for delete to authenticated
  using (bucket_id = 'interview-uploads' and (select private.my_role()) = 'doctor'
         and (storage.foldername(name))[1] = (select private.my_office_id())::text);

-- Card PDFs and SOPs: VFDA uploads; doctors can read their own office's.
create policy "office documents: admin full access" on storage.objects
  for all to authenticated
  using (bucket_id = 'office-documents' and (select private.is_admin()))
  with check (bucket_id = 'office-documents' and (select private.is_admin()));
create policy "office documents: doctor reads own office" on storage.objects
  for select to authenticated
  using (bucket_id = 'office-documents' and (select private.my_role()) = 'doctor'
         and (storage.foldername(name))[1] = (select private.my_office_id())::text);

commit;
